algorithm MatrixMultiplication
    dimension a[2, 2] as integer;
    dimension b[2, 2] as integer;
    dimension c[2, 2] as integer;
    define row as integer;
    define column as integer;
    define k as integer;
    define total as integer;
    for row <- 0 to 1 step 1 do
        for column <- 0 to 1 step 1 do
            read a[row, column];
        endFor
    endFor
    for row <- 0 to 1 step 1 do
        for column <- 0 to 1 step 1 do
            read b[row, column];
        endFor
    endFor
    for row <- 0 to 1 step 1 do
        for column <- 0 to 1 step 1 do
            total <- 0;
            for k <- 0 to 1 step 1 do
                total <- total + a[row, k] * b[k, column];
            endFor
            c[row, column] <- total;
        endFor
    endFor
    for row <- 0 to 1 step 1 do
        for column <- 0 to 1 step 1 do
            write c[row, column];
        endFor
    endFor
endAlgorithm
